// ---------------------------------------------------------------
// Construye el resumen diario a partir de los eventos del calendario
// y, opcionalmente, de las tareas pendientes de Google Sheets.
// ---------------------------------------------------------------
const zona = $now.zoneName;
const hoy = $now.startOf('day');
const hoyTexto = hoy.toFormat('yyyy-MM-dd');

function leerNodo(nombre) {
  try {
    return $(nombre).all().map((i) => i.json);
  } catch (error) {
    return []; // el nodo no se ejecutó o está desactivado
  }
}

function hora(dt) {
  return dt.toFormat('HH:mm');
}

function construirResumen(config, eventosRaw, tareasRaw) {
  // 1. Normalizar eventos (los de día completo usan start.date)
  const eventos = eventosRaw
    .filter((e) => e && e.start && e.status !== 'cancelled')
    .map((e) => {
      const todoElDia = !e.start.dateTime;
      const inicio = todoElDia ? DateTime.fromISO(e.start.date, { zone: zona }) : DateTime.fromISO(e.start.dateTime).setZone(zona);
      const fin = todoElDia ? DateTime.fromISO(e.end?.date || e.start.date, { zone: zona }) : DateTime.fromISO(e.end?.dateTime || e.start.dateTime).setZone(zona);
      return { titulo: e.summary || '(sin título)', lugar: e.location || '', todoElDia, inicio, fin };
    })
    .sort((a, b) => (a.todoElDia === b.todoElDia ? a.inicio - b.inicio : a.todoElDia ? -1 : 1));

  // 2. Huecos libres dentro de la jornada
  const [hIni, mIni] = String(config.inicioJornada || '08:00').split(':').map(Number);
  const [hFin, mFin] = String(config.finJornada || '20:00').split(':').map(Number);
  const inicioJornada = hoy.set({ hour: hIni, minute: mIni || 0 });
  const finJornada = hoy.set({ hour: hFin, minute: mFin || 0 });
  const huecos = [];
  let cursor = inicioJornada;
  for (const ev of eventos.filter((e) => !e.todoElDia)) {
    if (ev.inicio > cursor) huecos.push({ desde: cursor, hasta: ev.inicio < finJornada ? ev.inicio : finJornada });
    if (ev.fin > cursor) cursor = ev.fin;
  }
  if (cursor < finJornada) huecos.push({ desde: cursor, hasta: finJornada });
  const huecosUtiles = huecos.filter((h) => h.hasta.diff(h.desde, 'minutes').minutes >= 30);

  // 3. Tareas pendientes del chat configurado
  const tareas = tareasRaw
    .filter((t) => t && t.id && t.estado !== 'completada')
    .filter((t) => !config.chatId || String(t.chat_id) === String(config.chatId));
  const vencidas = tareas.filter((t) => t.fecha_limite && t.fecha_limite < hoyTexto);
  const paraHoy = tareas.filter((t) => t.fecha_limite === hoyTexto);
  const altas = tareas.filter((t) => t.prioridad === 'alta' && !vencidas.includes(t) && !paraHoy.includes(t));

  // 4. Mensaje
  const fechaLarga = $now.setLocale('es').toFormat("cccc d 'de' LLLL");
  const lineas = [`Resumen del ${fechaLarga}`, ''];

  lineas.push(`AGENDA (${eventos.length} ${eventos.length === 1 ? 'evento' : 'eventos'})`);
  if (eventos.length === 0) lineas.push('- Sin eventos en el calendario.');
  for (const ev of eventos) {
    const franja = ev.todoElDia ? 'Todo el día' : `${hora(ev.inicio)}-${hora(ev.fin)}`;
    lineas.push(`- ${franja}  ${ev.titulo}${ev.lugar ? ` (${ev.lugar})` : ''}`);
  }

  lineas.push('', 'TIEMPO LIBRE EN TU JORNADA');
  if (huecosUtiles.length === 0) lineas.push('- Sin huecos de 30 minutos o más.');
  for (const h of huecosUtiles) {
    const minutos = Math.round(h.hasta.diff(h.desde, 'minutes').minutes);
    const duracion = minutos >= 60 ? `${Math.floor(minutos / 60)} h ${minutos % 60 ? (minutos % 60) + ' min' : ''}`.trim() : `${minutos} min`;
    lineas.push(`- ${hora(h.desde)}-${hora(h.hasta)} (${duracion})`);
  }

  if (config.incluirTareas) {
    lineas.push('', 'TAREAS');
    lineas.push(`Vencidas: ${vencidas.length} | Para hoy: ${paraHoy.length} | Pendientes: ${tareas.length}`);
    const destacadas = [...vencidas, ...paraHoy, ...altas].slice(0, 8);
    for (const t of destacadas) {
      const marca = vencidas.includes(t) ? 'VENCIDA' : paraHoy.includes(t) ? 'hoy' : t.prioridad;
      lineas.push(`- [${marca}] ${t.titulo} (${t.id})`);
    }
  }

  return {
    chatId: String(config.chatId || ''),
    fecha: hoyTexto,
    totalEventos: eventos.length,
    totalTareasPendientes: tareas.length,
    tareasVencidas: vencidas.length,
    respuesta: lineas.join('\n'),
  };
}

const config = $('Configuración').first().json;
const eventos = leerNodo('Eventos de hoy');
const tareas = config.incluirTareas ? leerNodo('Tareas pendientes') : [];
return [{ json: construirResumen(config, eventos, tareas) }];
